CREATE TABLE IF NOT EXISTS ai_news_articles(id TEXT COLLATE "C" PRIMARY KEY,nation_id TEXT COLLATE "C" NOT NULL CHECK(nation_id IN('kindle','korund','aurelle')),title TEXT COLLATE "C" NOT NULL,body TEXT COLLATE "C" NOT NULL,created_at BIGINT NOT NULL,model TEXT COLLATE "C" NOT NULL,facts_json TEXT COLLATE "C" NOT NULL);
CREATE TABLE IF NOT EXISTS ai_news_jobs(id TEXT COLLATE "C" PRIMARY KEY,nation_id TEXT COLLATE "C" NOT NULL CHECK(nation_id IN('kindle','korund','aurelle')),utc_day TEXT COLLATE "C" NOT NULL,started_at BIGINT NOT NULL,status TEXT COLLATE "C" NOT NULL CHECK(status IN('running','published','failed')),failure_code TEXT COLLATE "C");
CREATE TABLE IF NOT EXISTS harimu_ai_reservations(request_id TEXT COLLATE "C" PRIMARY KEY,utc_day TEXT COLLATE "C" NOT NULL,next_utc_day TEXT COLLATE "C" NOT NULL,model TEXT COLLATE "C" NOT NULL,reserved_micro BIGINT NOT NULL CHECK(reserved_micro>0),started_at BIGINT NOT NULL,status TEXT COLLATE "C" NOT NULL CHECK(status IN('pending','finished','uncertain')));
CREATE TABLE IF NOT EXISTS korund_ration_queue(seq BIGINT PRIMARY KEY,request_id TEXT COLLATE "C" NOT NULL UNIQUE,clerk_user_id TEXT COLLATE "C" NOT NULL REFERENCES citizens(clerk_user_id),game_week BIGINT NOT NULL CHECK(game_week>=1),joined_at BIGINT NOT NULL,expires_at BIGINT NOT NULL CHECK(expires_at>joined_at),status TEXT COLLATE "C" NOT NULL DEFAULT 'waiting' CHECK(status IN('waiting','cancelled','redeemed')));
CREATE TABLE IF NOT EXISTS korund_queue_cancellations(request_id TEXT COLLATE "C" PRIMARY KEY,queue_id TEXT COLLATE "C" NOT NULL REFERENCES korund_ration_queue(request_id),clerk_user_id TEXT COLLATE "C" NOT NULL REFERENCES citizens(clerk_user_id),cancelled_at BIGINT NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS idx_korund_queue_waiting ON korund_ration_queue(clerk_user_id,game_week) WHERE status='waiting';
